def feature_names() -> list[str]:
    return [feature.name for feature in FEATURE_DEFINITIONS_V8]


def feature_definition_map() -> dict[str, V8FeatureDefinition]:
    return {feature.name: feature for feature in FEATURE_DEFINITIONS_V8}
